/** Real Spring/JDBC/JPA transactions, isolated H2. Carrier/provider are explicitly simulated. */
@SpringBootTest(properties={"spring.profiles.active=wallet-sandbox,wallet-test","wallet.sandbox.enabled=true","spring.datasource.driver-class-name=org.h2.Driver","spring.datasource.username=sa","spring.datasource.password=","spring.flyway.enabled=false","spring.jpa.hibernate.ddl-auto=validate","orders.mail.enabled=false"})
@AutoConfigureMockMvc
class VndWalletIntegrationTest extends CheckoutTestFixture {
    static java.sql.Connection schema;
    @DynamicPropertySource static void database(DynamicPropertyRegistry r)throws Exception{
        String mysql=System.getenv("BM_VND_WALLET_MYSQL_URL");
        String url=mysql==null?"jdbc:h2:mem:vndwallet;MODE=MySQL;DB_CLOSE_DELAY=-1;LOCK_TIMEOUT=10000":mysql;
        if(mysql==null){schema=DriverManager.getConnection(url,"sa","");BaselineSql.currentSchema(schema);}
        else{
            if(!url.matches("jdbc:mysql://127[.]0[.]0[.]1:13372/bm_wallet_qa_[A-Za-z0-9_]+[?].*"))throw new IllegalArgumentException("Refuse non-task MySQL endpoint");
            String password=Objects.requireNonNull(System.getenv("BM_VND_WALLET_MYSQL_PASSWORD"));
            schema=DriverManager.getConnection(url,"root",password);
            try(var result=schema.createStatement().executeQuery("select count(*) from information_schema.tables where table_schema=database()")){result.next();if(result.getInt(1)!=0)throw new IllegalStateException("Refuse nonempty test schema");}
            org.flywaydb.core.Flyway.configure().dataSource(url,"root",password).locations("classpath:db/migration").load().migrate();
            r.add("spring.datasource.username",()->"root");r.add("spring.datasource.password",()->password);r.add("spring.datasource.driver-class-name",()->"com.mysql.cj.jdbc.Driver");
        }
        r.add("spring.datasource.url",()->url);
    }
    @AfterAll static void close()throws Exception{schema.close();}
    @Autowired VndWallet wallet;@Autowired SandboxVndWalletProvider simulator;@Autowired PasswordEncoder passwords;
    @Autowired com.bonsaimarket.backend.marketplace.MarketplaceAccess access;@Autowired jakarta.persistence.EntityManager em;
    @Autowired org.springframework.transaction.PlatformTransactionManager manager;@Autowired com.bonsaimarket.backend.auth.AuthRateLimiter limiter;
    @Autowired com.bonsaimarket.backend.refund.RefundService refunds;
    String password;
    @BeforeEach void members(){password=UUID.randomUUID().toString();db.update("update users set password_hash=? where id=?",passwords.encode(password),buyer.getId());for(var u:List.of(buyer,other))db.update("insert into vnd_wallet_qa_members(user_id) values(?)",u.getId());}
    String key(){return UUID.randomUUID().toString();}
    void inspected(long order){db.update("update orders set status='DELIVERED' where id=?",order);db.update("insert into order_returns(order_id,kind,status,reason,inspection,restock,carrier_request_status,requested_at,received_at,inspected_at,updated_at) values(?,'BUYER_RETURN','INSPECTED','Returned','Inspected',false,'NOT_REQUIRED',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)",order);}
    @Test void inspectedPartialWalletRefundUsesOriginalDebitAndBalancesLedgerOnce()throws Exception{
        topup(500000);long id=checkout.place(buyer.getId(),payment(quote(buyer),key())).orderId();
        code("REFUND_RETURN_REQUIRED",()->refunds.request(buyer.getId(),id,"account",new com.bonsaimarket.backend.refund.RefundService.Write("Partial",new BigDecimal("10000"))));
        inspected(id);var r=refunds.request(buyer.getId(),id,"account",new com.bonsaimarket.backend.refund.RefundService.Write("Partial inspected return",new BigDecimal("10000"))).refund();
        r=refunds.decide(admin.getId(),r.id(),new com.bonsaimarket.backend.refund.RefundService.Decision("APPROVED","Approve inspected amount",r.revision()));
        long refund=r.id(),revision=r.revision();try(var pool=Executors.newFixedThreadPool(2)){var a=pool.submit(()->refunds.execute(admin.getId(),refund,revision));var b=pool.submit(()->refunds.execute(admin.getId(),refund,revision));assertEquals("SUCCEEDED",a.get(20,TimeUnit.SECONDS).status());assertEquals("SUCCEEDED",b.get(20,TimeUnit.SECONDS).status());}
        assertEquals(386000,wallet.balance(buyer.getId()).available());assertEquals(1,wallet.history(buyer.getId(),0,"REFUND","",null,null).totalElements());assertEquals("SANDBOX_PARTIALLY_REFUNDED",db.queryForObject("select status from order_payments where order_id=?",String.class,id));assertEquals(9,stock());balanced();
    }
    @Test void approvedFullWalletRefundBeforeHandoverDoesNotRestoreStockUntilCancellation(){
        topup(500000);long id=checkout.place(buyer.getId(),payment(quote(buyer),key())).orderId();var r=refunds.request(buyer.getId(),id,"account",new com.bonsaimarket.backend.refund.RefundService.Write("Full cancellation review")).refund();r=refunds.decide(admin.getId(),r.id(),new com.bonsaimarket.backend.refund.RefundService.Decision("APPROVED","Approved full",r.revision()));assertEquals("SUCCEEDED",refunds.execute(admin.getId(),r.id(),r.revision()).status());assertEquals(500000,wallet.balance(buyer.getId()).available());assertEquals(9,stock());management.cancelByBuyer(buyer.getId(),id);assertEquals(10,stock());assertEquals(1,wallet.history(buyer.getId(),0,"REFUND","",null,null).totalElements());balanced();
    }
    VndWallet.Transaction topup(long n){var t=wallet.request(buyer.getId(),"TOP_UP",BigDecimal.valueOf(n),key(),null);return wallet.simulate(buyer.getId(),t.id(),"COMPLETED");}
    CheckoutService.Place payment(CheckoutService.QuoteView q,String key){return new CheckoutService.Place(q.id(),key,"WALLET_SANDBOX","");}
    void balanced(){assertEquals(0,db.queryForObject("select count(*) from (select journal_id from vnd_wallet_entries group by journal_id having sum(available_delta+held_delta)<>0) q",Integer.class));var r=(Map<?,?>)wallet.reconcile(admin.getId());for(String field:List.of("balanceDifferences","unbalancedJournals","obligationDifferences","obligationLedgerDifferences","paymentDifferences","providerDifferences"))assertTrue(((List<?>)r.get(field)).isEmpty(),field);}

    @Test void openingWalletDoesNotGrantFundsAndCreditsRemainIndependent(){assertTrue(wallet.balance(buyer.getId()).enabled());assertEquals(0,wallet.balance(buyer.getId()).available());assertEquals(0,db.queryForObject("select count(*) from vnd_wallet_accounts where owner_id=?",Long.class,buyer.getId()));topup(500000);assertEquals(0,db.queryForObject("select count(*) from credit_accounts where owner_id=?",Long.class,buyer.getId()));balanced();}
    @Test void topupCreditsOnlyOnSignedConfirmationAndReplayIsExactlyOnce(){var k=key();var t=wallet.request(buyer.getId(),"TOP_UP",BigDecimal.valueOf(500000),k,null);assertEquals("PENDING",t.status());assertEquals(0,wallet.balance(buyer.getId()).available());assertEquals(t.id(),wallet.request(buyer.getId(),"TOP_UP",BigDecimal.valueOf(500000),k,null).id());var event=simulator.simulate(t.id(),t.amount(),"COMPLETED");wallet.confirm(buyer.getId(),event);wallet.confirm(buyer.getId(),event);assertEquals(500000,wallet.balance(buyer.getId()).available());assertEquals(1,db.queryForObject("select count(*) from order_notification_outbox where dedup_key=?",Long.class,"INAPP:VND_WALLET:"+t.id()+":COMPLETED:"+buyer.getId()));assertEquals(1,db.queryForObject("select count(*) from vnd_wallet_provider_events where transaction_id=?",Long.class,t.id()));code("WALLET_REQUEST_CONFLICT",()->wallet.request(buyer.getId(),"TOP_UP",BigDecimal.valueOf(600000),k,null));balanced();}
    @Test void signatureMismatchAmountMismatchUnknownAndForeignConfirmationsFailClosed(){var t=wallet.request(buyer.getId(),"TOP_UP",BigDecimal.valueOf(1000),key(),null);var e=simulator.simulate(t.id(),1000,"COMPLETED");code("WALLET_SIGNATURE_INVALID",()->wallet.confirm(buyer.getId(),new VndWalletProvider.Confirmation(e.eventId(),e.transactionId(),e.amount(),e.currency(),e.outcome(),"forged")));code("WALLET_CONFIRMATION_MISMATCH",()->wallet.confirm(buyer.getId(),simulator.simulate(t.id(),2000,"COMPLETED")));code("NOT_FOUND",()->wallet.confirm(other.getId(),e));code("NOT_FOUND",()->wallet.confirm(buyer.getId(),simulator.simulate(key(),1000,"COMPLETED")));assertEquals(0,wallet.balance(buyer.getId()).available());balanced();}
    @Test void failedTopupNeverCreatesCreditAndContradictoryReplayIsRejected(){var t=wallet.request(buyer.getId(),"TOP_UP",BigDecimal.valueOf(1000),key(),null);wallet.simulate(buyer.getId(),t.id(),"FAILED");code("WALLET_FINAL_STATE",()->wallet.simulate(buyer.getId(),t.id(),"COMPLETED"));assertEquals(0,wallet.balance(buyer.getId()).available());balanced();}
    @Test void withdrawalRequiresStepUpBankAndFundsThenFailureReleasesExactlyOnce(){topup(100000);code("WALLET_STEP_UP_REQUIRED",()->wallet.request(buyer.getId(),"WITHDRAWAL",BigDecimal.valueOf(80000),key(),"wrong"));code("WALLET_BANK_REQUIRED",()->wallet.request(buyer.getId(),"WITHDRAWAL",BigDecimal.valueOf(80000),key(),password));wallet.linkBank(buyer.getId());var k=key();var t=wallet.request(buyer.getId(),"WITHDRAWAL",BigDecimal.valueOf(80000),k,password);assertEquals(20000,wallet.balance(buyer.getId()).available());assertEquals(80000,wallet.balance(buyer.getId()).held());assertEquals(t.id(),wallet.request(buyer.getId(),"WITHDRAWAL",BigDecimal.valueOf(80000),k,null).id());wallet.simulate(buyer.getId(),t.id(),"FAILED");wallet.simulate(buyer.getId(),t.id(),"FAILED");assertEquals(100000,wallet.balance(buyer.getId()).available());assertEquals(0,wallet.balance(buyer.getId()).held());balanced();}
    @Test void completedWithdrawalDebitsOnceAndInsufficientRequestRollsBack(){topup(100000);wallet.linkBank(buyer.getId());var t=wallet.request(buyer.getId(),"WITHDRAWAL",BigDecimal.valueOf(80000),key(),password);wallet.simulate(buyer.getId(),t.id(),"COMPLETED");wallet.simulate(buyer.getId(),t.id(),"COMPLETED");assertEquals(20000,wallet.balance(buyer.getId()).available());assertEquals(0,wallet.balance(buyer.getId()).held());code("WALLET_INSUFFICIENT_FUNDS",()->wallet.request(buyer.getId(),"WITHDRAWAL",BigDecimal.valueOf(30000),key(),password));assertEquals(2,wallet.history(buyer.getId(),0,"","",null,null).totalElements());balanced();}
    @Test void concurrentDebitsNeverOverspend()throws Exception{topup(100000);wallet.linkBank(buyer.getId());try(var pool=Executors.newFixedThreadPool(2)){var start=new CountDownLatch(1);var calls=new ArrayList<Future<Boolean>>();for(int i=0;i<2;i++)calls.add(pool.submit(()->{start.await();try{wallet.request(buyer.getId(),"WITHDRAWAL",BigDecimal.valueOf(80000),key(),password);return true;}catch(MarketplaceException e){assertEquals("WALLET_INSUFFICIENT_FUNDS",e.code);return false;}}));start.countDown();int success=0;for(var f:calls)if(f.get(20,TimeUnit.SECONDS))success++;assertEquals(1,success);}assertEquals(20000,wallet.balance(buyer.getId()).available());assertEquals(80000,wallet.balance(buyer.getId()).held());balanced();}
    @Test void walletCheckoutIsAtomicIdempotentRecoverableAndCannotCreateExternalShipment(){topup(500000);var b=payment(quote(buyer),key());var first=checkout.place(buyer.getId(),b);assertEquals("SANDBOX_PAID",first.paymentStatus());assertEquals(376000,wallet.balance(buyer.getId()).available());assertEquals(first.orderId(),checkout.place(buyer.getId(),b).orderId());assertEquals(first.orderId(),checkout.recover(buyer.getId(),b.idempotencyKey()).orderId());assertEquals(9,stock());assertEquals(0,cart.view(buyer.getId()).quantity());assertEquals("SANDBOX_HELD",db.queryForObject("select status from vnd_wallet_obligations where order_id=?",String.class,first.orderId()));management.transition(seller.getId(),false,first.orderId(),"CONFIRMED");code("SANDBOX_SHIPMENT_BLOCKED",()->shipping.create(seller.getId(),first.orderId()));balanced();}
    @Test void insufficientCheckoutRollsBackOrderInventoryLedgerAndOutbox(){var q=quote(buyer);code("WALLET_INSUFFICIENT_FUNDS",()->checkout.place(buyer.getId(),payment(q,key())));assertEquals(10,stock());assertEquals(1,cart.view(buyer.getId()).quantity());assertEquals(0,db.queryForObject("select count(*) from orders where buyer_user_id=?",Long.class,buyer.getId()));assertEquals(0,wallet.history(buyer.getId(),0,"","",null,null).totalElements());assertEquals(0,db.queryForObject("select count(*) from order_notification_outbox where recipient_user_id=?",Long.class,buyer.getId()));balanced();}
    @Test void expiredAndChangedPriceQuotesNeverDebitWallet(){topup(500000);var q=quote(buyer);db.update("update checkout_quotes set expires_at=? where id=?",access.now().minusHours(1),q.id());code("QUOTE_EXPIRED",()->checkout.place(buyer.getId(),payment(q,key())));var fresh=quote(buyer);db.update("update products set price=100001 where id=?",product.getId());code("QUOTE_CHANGED",()->checkout.place(buyer.getId(),payment(fresh,key())));assertEquals(500000,wallet.balance(buyer.getId()).available());assertEquals(10,stock());balanced();}
    @Test void cancellationCompensatesFullAmountOnlyOnceAndProjectsActualRefund(){topup(500000);var r=checkout.place(buyer.getId(),payment(quote(buyer),key()));management.cancelByBuyer(buyer.getId(),r.orderId(),"QA cancellation");assertEquals(500000,wallet.balance(buyer.getId()).available());assertEquals(10,stock());var tx=new org.springframework.transaction.support.TransactionTemplate(manager);tx.execute(s->{wallet.refundCancelled(em.find(com.bonsaimarket.backend.order.Order.class,r.orderId()));return null;});assertEquals(1,wallet.history(buyer.getId(),0,"REFUND","",null,null).totalElements());var overview=refunds.overview(buyer.getId(),r.orderId(),"account");assertEquals("COMPLETED",overview.sandboxWalletRefund().get("status"));String refundId=overview.sandboxWalletRefund().get("id").toString();assertEquals(2,db.queryForObject("select count(*) from order_notification_outbox where dedup_key like ?",Long.class,"INAPP:VND_WALLET:"+refundId+":%:"+buyer.getId()));code("WALLET_REFUND_VIA_CANCELLATION",()->refunds.request(buyer.getId(),r.orderId(),"account",new com.bonsaimarket.backend.refund.RefundService.Write("No double refund")));balanced();}
    @Test void serverFiltersWholeHistoryAndOwnerDetailsRemainPrivate(){for(int i=0;i<3;i++)topup(1000);var pending=wallet.request(buyer.getId(),"TOP_UP",BigDecimal.valueOf(2000),key(),null);assertEquals(3,wallet.history(buyer.getId(),0,"TOP_UP","COMPLETED",null,null).totalElements());assertEquals(1,wallet.history(buyer.getId(),0,"","PENDING",LocalDate.now().minusDays(1),LocalDate.now().plusDays(1)).totalElements());assertEquals(0,wallet.history(other.getId(),0,"","",null,null).totalElements());code("NOT_FOUND",()->wallet.detail(other.getId(),pending.id()));code("VALIDATION_FAILED",()->wallet.history(buyer.getId(),0,"GRANT","",null,null));balanced();}
    @Test void guestCsrfRoleForgedOwnerAndLedgerWritesAreRejected()throws Exception{mvc.perform(get("/api/account/vnd-wallet")).andExpect(status().isUnauthorized());mvc.perform(post("/api/account/vnd-wallet/requests").with(as(buyer)).contentType("application/json").content("{}")).andExpect(status().isForbidden());mvc.perform(get("/api/account/vnd-wallet").with(as(seller))).andExpect(status().isForbidden());mvc.perform(post("/api/account/vnd-wallet/requests").with(as(buyer)).with(csrf()).contentType("application/json").content("{\"type\":\"TOP_UP\",\"amount\":1000,\"requestKey\":\"abcdefghijklmnop\",\"ownerId\":"+other.getId()+",\"balanceAfter\":999999}")).andExpect(status().isOk());assertEquals(1,wallet.history(buyer.getId(),0,"","",null,null).totalElements());assertEquals(0,wallet.history(other.getId(),0,"","",null,null).totalElements());mvc.perform(put("/api/account/vnd-wallet/ledger").with(as(buyer)).with(csrf()).contentType("application/json").content("{}")).andExpect(status().is4xxClientError());}
    @Test void amountLimitsAndDisabledProductionGateFailClosed(){for(String value:List.of("1","1000.5","10000001","-1000"))code("VALIDATION_FAILED",()->wallet.request(buyer.getId(),"TOP_UP",new BigDecimal(value),key(),null));var env=new MockEnvironment();env.setActiveProfiles("production","wallet-sandbox");var closed=new VndWallet(db,access,em,simulator,passwords,env,true,limiter);assertFalse(closed.enabled());assertNull(closed.balance(buyer.getId()).available());code("WALLET_DISABLED",()->closed.request(buyer.getId(),"TOP_UP",BigDecimal.valueOf(1000),key(),null));}
    @Test void repeatedStepUpAttemptsAndDailyTopupLimitsAreEnforced(){for(int i=0;i<5;i++)code("WALLET_STEP_UP_REQUIRED",()->wallet.request(buyer.getId(),"WITHDRAWAL",BigDecimal.valueOf(1000),key(),"wrong"));code("WALLET_STEP_UP_LIMIT",()->wallet.request(buyer.getId(),"WITHDRAWAL",BigDecimal.valueOf(1000),key(),password));for(int i=0;i<5;i++)wallet.request(buyer.getId(),"TOP_UP",BigDecimal.valueOf(10000000),key(),null);code("WALLET_DAILY_LIMIT",()->wallet.request(buyer.getId(),"TOP_UP",BigDecimal.valueOf(1000),key(),null));}
    @Test void mysqlLedgerRejectsInPlaceEditsAndDeletes(){
        Assumptions.assumeTrue(System.getenv("BM_VND_WALLET_MYSQL_URL")!=null,"MySQL-only trigger evidence; H2 adapter omits triggers");topup(1000);
        String id=db.queryForObject("select j.id from vnd_wallet_journals j join vnd_wallet_transactions t on t.id=j.transaction_id where t.owner_id=?",String.class,buyer.getId());
        for(String sql:List.of("update vnd_wallet_entries set available_delta=available_delta where journal_id=?","delete from vnd_wallet_entries where journal_id=?","update vnd_wallet_journals set phase=phase where id=?","delete from vnd_wallet_journals where id=?")){
            var error=assertThrows(org.springframework.dao.DataAccessException.class,()->db.update(sql,id));assertTrue(error.getMessage().contains("append only"));
        }balanced();
    }
    @Test void concurrentWalletCheckoutUsesOneOrderAndOneDebit()throws Exception{
        topup(500000);var body=payment(quote(buyer),key());try(var pool=Executors.newFixedThreadPool(2)){var gate=new CountDownLatch(1);var a=pool.submit(()->{gate.await();return checkout.place(buyer.getId(),body);});var b=pool.submit(()->{gate.await();return checkout.place(buyer.getId(),body);});gate.countDown();assertEquals(a.get(20,TimeUnit.SECONDS).orderId(),b.get(20,TimeUnit.SECONDS).orderId());}
        assertEquals(376000,wallet.balance(buyer.getId()).available());assertEquals(9,stock());assertEquals(1,wallet.history(buyer.getId(),0,"WALLET_PAYMENT","",null,null).totalElements());balanced();
    }
    @Test void walletBuyNowRetainsCartAndBindsMethodOnAttemptReplay(){
        topup(500000);var address=addresses.create(buyer.getId(),delivery());var q=checkout.quote(buyer.getId(),new CheckoutDtos.Request(CheckoutDtos.Source.BUY_NOW,address.id(),product.getId(),1,"",store.getId()));String shipping=q.shippingQuotes().getFirst().id();var receipt=checkout.submit(buyer.getId(),q.quoteId(),shipping,"WALLET_SANDBOX");assertEquals(receipt,checkout.submit(buyer.getId(),q.quoteId(),shipping,"WALLET_SANDBOX"));code("IDEMPOTENCY_CONFLICT",()->checkout.submit(buyer.getId(),q.quoteId(),shipping,"COD"));assertEquals(1,cart.view(buyer.getId()).quantity());assertEquals(376000,wallet.balance(buyer.getId()).available());balanced();
    }
    @Test void reconciliationDetectsObligationProjectionDriftWithoutEditingLedger(){
        topup(500000);var order=checkout.place(buyer.getId(),payment(quote(buyer),key()));var tx=new org.springframework.transaction.support.TransactionTemplate(manager);tx.execute(s->{db.update("update vnd_wallet_obligations set status='REFUNDED' where order_id=?",order.orderId());var r=(Map<?,?>)wallet.reconcile(admin.getId());assertFalse(((List<?>)r.get("obligationLedgerDifferences")).isEmpty());s.setRollbackOnly();return null;});balanced();
    }
}
